1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { MailboxesView } from "@/components/nx/MailboxesView";
4	import type { PlanOpt, SubscriptionRow } from "@/components/customer/EmailHosting";
5	import { CloudflareResultBanner } from "@/components/customer/CloudflareConnect";
6	import { annualDiscountPct } from "@/lib/annual-discount";
7	
8	export const dynamic = "force-dynamic";
9	
10	export default async function EmailHostingPage() {
11	  const user = await requireUser();
12	
13	  const [domains, plans, subscriptions, annualPct] = await Promise.all([
14	    db.domain.findMany({
15	      where: { userId: user.id, status: "ACTIVE" },
16	      orderBy: { name: "asc" },
17	    }),
18	    db.emailPlan.findMany({
19	      where: { active: true },
20	      orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
21	    }),
22	    db.emailSubscription.findMany({
23	      where: { userId: user.id, status: { not: "CANCELLED" } },
24	      include: { emailPlan: true, mailboxes: { orderBy: { createdAt: "asc" } } },
25	      orderBy: { createdAt: "desc" },
26	    }),
27	    annualDiscountPct(),
28	  ]);
29	
30	  const planOpts: PlanOpt[] = plans.map((p) => ({
31	    id: p.id,
32	    name: p.name,
33	    mailboxes: p.mailboxes,
34	    storageGB: p.storageGB,
35	    priceCents: p.priceCents,
36	    termMonths: p.termMonths,
37	  }));
38	
39	  const subRows: SubscriptionRow[] = subscriptions.map((s) => ({
40	    id: s.id,
41	    domainName: s.domainName,
42	    status: s.status,
43	    external: s.external,
44	    verified: s.verified,
45	    planName: s.emailPlan.name,
46	    planMailboxes: s.emailPlan.mailboxes,
47	    planStorageGB: s.emailPlan.storageGB,
48	    expiresAt: s.expiresAt ? s.expiresAt.toISOString() : null,
49	    mailboxes: s.mailboxes.map((m) => ({
50	      id: m.id,
51	      address: m.address,
52	      // The row's REAL status. This was deliberately dropped here, which is why
53	      // every mailbox rendered a hardcoded amber "Provisioning" badge forever —
54	      // including one whose Mailcow provisioning had already come back FAILED,
55	      // so mail to it bounced while the panel implied it was still on its way.
56	      status: m.status,
57	      createdAt: m.createdAt.toISOString(),
58	    })),
59	  }));
60	
61	  return (
62	    <div className="flex flex-col gap-3">
63	      {/* Outcome of a "Connect Cloudflare" round trip, if we just came back from one. */}
64	      <CloudflareResultBanner />
65	
66	      <MailboxesView
67	        domains={domains.map((d) => d.name)}
68	        plans={planOpts}
69	        subscriptions={subRows}
70	        balanceCents={user.balanceCents}
71	        annualDiscountPct={annualPct}
72	        email={user.email}
73	      />
74	    </div>
75	  );
76	}
