1	import Link from "next/link";
2	import { requireUser } from "@/lib/auth";
3	import { EmptyState } from "@/components/ui/primitives";
4	import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
5	import {
6	  listFolders,
7	  listMessages,
8	  getMailboxes,
9	} from "@/lib/actions-mail";
10	import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
11	import { mailAccessState, type MailAccessState } from "@/lib/mail/imap";
12	import { MailClient } from "@/components/customer/mail/MailClient";
13	
14	export const dynamic = "force-dynamic";
15	
16	export const metadata = { title: "Mail — Nxeon" };
17	
18	export default async function MailPage({
19	  searchParams,
20	}: {
21	  searchParams: Promise<{ mailbox?: string }>;
22	}) {
23	  const user = await requireUser();
24	  const { mailbox: requested } = await searchParams;
25	
26	  let folders: MailFolder[] = [];
27	  let mailboxes: MailboxInfo[] = [];
28	  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
29	  let inboxPath = "INBOX";
30	  let signature = "";
31	  let active: string | undefined;
32	  let failed = false;
33	
34	  const wanted = requested?.trim().toLowerCase();
35	
36	  try {
37	    if (wanted) {
38	      // Honour `?mailbox=` (the per-mailbox "Open inbox" link on the Business
39	      // Email page) but ONLY when the address is one this user actually owns.
40	      // `getMailboxes` is already scoped to their own subscriptions, so an
41	      // address outside that list is dropped rather than passed to
42	      // `resolveMailbox` — a bad or hostile value lands on the default mailbox
43	      // instead of turning the whole page into an error state. The mailbox list
44	      // has to be resolved first here, hence the extra round trip.
45	      mailboxes = await getMailboxes();
46	      if (mailboxes.length === 0) throw new Error("no mailbox");
47	      if (mailboxes.some((m) => m.address.toLowerCase() === wanted)) active = wanted;
48	      folders = await listFolders(active);
49	    } else {
50	      // No deep link: `resolveMailbox(undefined)` and `getMailboxes` both order by
51	      // createdAt asc, so they agree on which mailbox is the default and the two
52	      // IMAP round trips can overlap — this is the common load and it stays fast.
53	      const [f, mb] = await Promise.all([listFolders(), getMailboxes()]);
54	      folders = f;
55	      mailboxes = mb;
56	    }
57	
58	    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
59	    list = await listMessages(inboxPath, 1, undefined, active);
60	    // Signature for the active mailbox (best effort — never fail the page on it).
61	    signature = await getMailboxSettings(active)
62	      .then((s) => s.signature)
63	      .catch(() => "");
64	  } catch {
65	    failed = true;
66	  }
67	
68	  if (failed || folders.length === 0) {
69	    // WHY a diagnosis instead of one message: this page used to render a single
70	    // "No mailbox connected" for every cause, so "you have no email plan",
71	    // "your domain isn't verified yet", "your mailbox exists but we never
72	    // captured its password" and "the mail server is down" all read as the same
73	    // dead end. `mailAccessState` also runs Mailcow discovery, so a mailbox that
74	    // exists on the mail server without a local row is adopted BEFORE we tell
75	    // anyone they don't have one — the "it's not detecting the mailbox I already
76	    // have" report.
77	    const state = await mailAccessState(user.id).catch(
78	      () => ({ kind: "no-subscription" }) as MailAccessState,
79	    );
80	    return (
81	      // The app frame has no padding of its own, so the empty state has to
82	      // carry its own gutter and centre itself in the height it is given.
83	      <div className="grid h-full place-items-center px-4">
84	        <div className="w-full max-w-2xl">
85	          <MailUnavailable state={state} />
86	        </div>
87	      </div>
88	    );
89	  }
90	
91	  // No hero, no padding, no wrapper. The shell hands this route an app frame
92	  // (`appFrame` in components/nx/Shell): a <main> with no padding sized to the
93	  // exact viewport left over. So the client fills it edge to edge and flush
94	  // under the header, and the window never scrolls — the rail, the list and
95	  // the reading pane each scroll on their own.
96	  return (
97	    <MailClient
98	      initialFolders={folders}
99	      initialMailboxes={mailboxes}
100	      initialList={list}
101	      initialFolderPath={inboxPath}
102	      initialSignature={signature}
103	      initialActiveAddress={active}
104	    />
105	  );
106	}
107	
108	/** One empty state per real cause, each with the action that actually fixes it. */
109	function MailUnavailable({ state }: { state: MailAccessState }) {
110	  const emailLink = (
111	    <Link href="/dashboard/email" className="btn-primary">
112	      Business Email
113	    </Link>
114	  );
115	
116	  switch (state.kind) {
117	    case "no-subscription":
118	      return (
119	        <EmptyState
120	          title="No email plan yet"
121	          sub="Webmail needs a mailbox on one of your domains. Add business email to a domain and your inbox appears here."
122	          action={
123	            <Link href="/dashboard/email" className="btn-primary">
124	              Set up email
125	            </Link>
126	          }
127	        />
128	      );
129	
130	    case "unverified-domain":
131	      return (
132	        <EmptyState
133	          title="Finish verifying your domain"
134	          sub={`${state.domains.join(", ")} still needs its DNS records published and verified. Mailboxes can't go live — and mail won't route — until that succeeds.`}
135	          action={emailLink}
136	        />
137	      );
138	
139	    case "no-mailbox":
140	      return (
141	        <EmptyState
142	          title="No mailbox created yet"
143	          sub={`${state.domains.join(", ")} is verified and ready. Create your first mailbox (like you@${state.domains[0] ?? "yourdomain.com"}) to start using webmail.`}
144	          action={emailLink}
145	        />
146	      );
147	
148	    case "no-password":
149	      return (
150	        <EmptyState
151	          title="Reset your mailbox password to continue"
152	          sub={`We can see ${state.address} on the mail server, but we don't hold a password for it — so we can't sign in to IMAP on your behalf. Reset the password on the Business Email page and webmail will open here.`}
153	          action={emailLink}
154	        />
155	      );
156	
157	    case "server-unreachable":
158	      return (
159	        <EmptyState
160	          title="Couldn't reach your mailbox"
161	          sub={`${state.address} is set up, but the mail server didn't answer just now. This is usually temporary — reload in a moment. If it keeps happening, open a ticket and we'll look at the server.`}
162	          action={
163	            <Link href="/dashboard/support" className="btn-secondary">
164	              Contact support
165	            </Link>
166	          }
167	        />
168	      );
169	
170	    default:
171	      return (
172	        <EmptyState
173	          title="No mailbox connected"
174	          sub="We couldn't reach a mailbox for your account."
175	          action={emailLink}
176	        />
177	      );
178	  }
179	}
