1	"use client";
2	
3	/* The Business Email management screen, rebuilt.
4	 *
5	 * WHAT WAS WRONG. The page opened with a hero, then an explainer, then a
6	 * ~480-line three-step PURCHASE WIZARD, then a marketing trust strip (99.9%
7	 * uptime / 24-7 support / instant setup) — and only then "Your email
8	 * subscriptions", the reason anyone signed in. Store copy and a checkout flow
9	 * sat above the customer's own mailboxes on an authenticated account page, and
10	 * every mailbox was buried two clicks deep inside a collapsed domain accordion.
11	 *
12	 * WHAT THIS DOES INSTEAD. It leads with the thing you came for. Mailboxes are a
13	 * flat, always-visible list; the domain/DNS/deliverability machinery moves to
14	 * its own tab, because it is something you touch once at setup and then only
15	 * when mail breaks; and buying more moves to a third tab so it is reachable
16	 * without being in the way. The purchase wizard only leads when there is
17	 * genuinely nothing to manage yet — which is the one moment it IS the page.
18	 *
19	 * The wizard, DNS setup, deliverability check, mailbox row and add-mailbox form
20	 * are the SAME components as before, re-composed. This is a restructure, not a
21	 * reimplementation: none of the behaviour they carry (Mailcow provisioning,
22	 * password reveal/reset, retry, DNS verification) is touched.
23	 */
24	
25	import { useMemo, useState } from "react";
26	import Link from "next/link";
27	import { Icon } from "./Icon";
28	import { Panel, StatCard } from "./PageShell";
29	import { MailAurora } from "./MailAurora";
30	import { EmailDnsSetup } from "@/components/customer/EmailDnsSetup";
31	import {
32	  OrderPanel,
33	  DeliverabilityPanel,
34	  AddMailboxForm,
35	  MailboxItem,
36	  attentionReason,
37	  type PlanOpt,
38	  type SubscriptionRow,
39	} from "@/components/customer/EmailHosting";
40	
41	const TABS = [
42	  { key: "mailboxes", label: "Mailboxes", icon: "envelope" },
43	  { key: "domains", label: "Domains & DNS", icon: "globe" },
44	  { key: "add", label: "Add email", icon: "plus" },
45	] as const;
46	type TabKey = (typeof TABS)[number]["key"];
47	
48	export function MailboxesView({
49	  subscriptions,
50	  domains,
51	  plans,
52	  balanceCents,
53	  annualDiscountPct,
54	  email,
55	}: {
56	  subscriptions: SubscriptionRow[];
57	  domains: string[];
58	  plans: PlanOpt[];
59	  balanceCents: number;
60	  annualDiscountPct: number;
61	  email: string;
62	}) {
63	  const [tab, setTab] = useState<TabKey>("mailboxes");
64	
65	  const subbed = new Set(subscriptions.map((s) => s.domainName));
66	  const suggestedDomains = domains.filter((d) => !subbed.has(d));
67	
68	  const stats = useMemo(() => {
69	    const used = subscriptions.reduce((n, s) => n + s.mailboxes.length, 0);
70	    const included = subscriptions.reduce((n, s) => n + s.planMailboxes, 0);
71	    // Storage is a PER-MAILBOX allowance, and it can differ between plans when
72	    // an account holds more than one subscription. Showing one plan's number as
73	    // if it were everyone's would be a quiet lie, so a mixed account says so.
74	    const sizes = new Set(subscriptions.map((s) => s.planStorageGB));
75	    const storage = sizes.size === 1 ? `${[...sizes][0]} GB` : "Mixed";
76	    // Renewal dates are real, so the soonest one is the one worth surfacing.
77	    const next = subscriptions
78	      .map((s) => s.expiresAt)
79	      .filter((x): x is string => !!x)
80	      .sort()[0];
81	    const needsAttention = subscriptions.filter((s) => attentionReason(s) !== null).length;
82	    return { used, included, storage, next, needsAttention };
83	  }, [subscriptions]);
84	
85	  /* Nothing to manage yet. This is the ONE state where the purchase flow is
86	     genuinely the page, so it gets it — no tabs to click through first. */
87	  if (subscriptions.length === 0) {
88	    return (
89	      <>
90	        <MailAurora />
91	        <div className="relative z-10 mx-auto flex w-full max-w-[1520px] flex-col gap-4">
92	          <MailHero
93	            headline={["Email on", "your own domain."]}
94	            sub="Professional mailboxes on a domain you own — set up in a couple of minutes, and read and sent right here in the portal."
95	          />
96	          {plans.length > 0 && (
97	            <OrderPanel
98	              suggestedDomains={suggestedDomains}
99	              plans={plans}
100	              balanceCents={balanceCents}
101	              annualDiscountPct={annualDiscountPct}
102	              email={email}
103	            />
104	          )}
105	        </div>
106	      </>
107	    );
108	  }
109	
110	  const firstMailbox = subscriptions.flatMap((s) => s.mailboxes)[0];
111	
112	  return (
113	    <>
114	      <MailAurora />
115	      <div className="relative z-10 mx-auto flex w-full max-w-[1520px] flex-col gap-4">
116	        <MailHero
117	          headline={["Your domain.", "Your mailboxes."]}
118	          sub="Create mailboxes on the domains you own, keep their DNS and deliverability healthy, and read it all without leaving the portal."
119	          action={
120	            firstMailbox ? (
121	              <Link
122	                href={`/dashboard/mail?mailbox=${encodeURIComponent(firstMailbox.address)}`}
123	                className="btn-primary h-[38px] gap-1.5 px-4 text-[13px]"
124	              >
125	                <Icon name="inbox" size={14} />
126	                Open inbox
127	              </Link>
128	            ) : undefined
129	          }
130	        />
131	      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
132	        <StatCard bareIcon icon="envelope" value={`${stats.used}`} label={`of ${stats.included} mailboxes used`} />
133	        <StatCard
134	          bareIcon
135	          icon="globe"
136	          tone="violet"
137	          value={`${subscriptions.length}`}
138	          label={`domain${subscriptions.length === 1 ? "" : "s"} with mail`}
139	        />
140	        <StatCard bareIcon icon="database" tone="mint" value={stats.storage} label="storage per mailbox" />
141	        <StatCard
142	          bareIcon
143	          icon="refresh"
144	          tone={stats.needsAttention ? "amber" : "blue"}
145	          volatileValue
146	          value={stats.next ? new Date(stats.next).toLocaleDateString() : "—"}
147	          label={stats.next ? "next renewal" : "no renewal date"}
148	        />
149	      </div>
150	
151	      {/* Same underlined-text tabs as Billing, Support and Team. */}
152	      <div className="flex flex-wrap items-center gap-6 border-b border-rim-soft">
153	        {TABS.map((t) => (
154	          <button
155	            key={t.key}
156	            type="button"
157	            onClick={() => setTab(t.key)}
158	            className={"nx-tab flex items-center gap-1.5 " + (tab === t.key ? "nx-tab-on" : "")}
159	          >
160	            <Icon name={t.icon} size={13} className="opacity-80" />
161	            {t.label}
162	            {t.key === "domains" && stats.needsAttention > 0 && (
163	              <span className="rounded-full bg-[rgba(240,180,60,0.18)] px-1.5 text-[10px] font-bold text-amber">
164	                {stats.needsAttention}
165	              </span>
166	            )}
167	          </button>
168	        ))}
169	      </div>
170	
171	      {tab === "mailboxes" && <MailboxesTab subscriptions={subscriptions} />}
172	      {tab === "domains" && <DomainsTab subscriptions={subscriptions} />}
173	      {tab === "add" && (
174	        <>
175	          {plans.length > 0 ? (
176	            <OrderPanel
177	              suggestedDomains={suggestedDomains}
178	              plans={plans}
179	              balanceCents={balanceCents}
180	              annualDiscountPct={annualDiscountPct}
181	              email={email}
182	              // No trust strip here: this is an existing customer, standing in
183	              // their own account, looking at mailboxes they already own.
184	              showReassurance={false}
185	            />
186	          ) : (
187	            <Panel title="No plans available">
188	              <p className="text-[13px] text-tx-mute">
189	                There are no email plans on sale right now. Open a ticket and we&apos;ll sort it out.
190	              </p>
191	            </Panel>
192	          )}
193	        </>
194	        )}
195	      </div>
196	    </>
197	  );
198	}
199	
200	/* The page's opening. Mailboxes was still on PageShell's compact header while
201	   Billing and Team had moved to a two-line gradient headline over their own
202	   aurora — which is exactly why this page read flat next to them. Same class of
203	   hero, its own words. */
204	function MailHero({
205	  headline,
206	  sub,
207	  action,
208	}: {
209	  headline: [string, string];
210	  sub: string;
211	  action?: React.ReactNode;
212	}) {
213	  return (
214	    <header className="relative flex flex-col gap-4 pb-1 lg:flex-row lg:items-center lg:justify-between">
215	      <div className="flex min-w-0 max-w-[620px] flex-col gap-3">
216	        <span className="flex items-center gap-1 text-[12.5px] font-semibold text-tx-faint">
217	          <span className="text-magenta">›</span> Mail
218	        </span>
219	        <h1 className="text-[36px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[44px]">
220	          {headline[0]}
221	          <br />
222	          <span className="bg-gradient-to-r from-[#18e0c2] via-[#5fd0ff] to-[#a23bff] bg-clip-text text-transparent">
223	            {headline[1]}
224	          </span>
225	        </h1>
226	        <p className="max-w-[56ch] text-[13.5px] leading-[1.6] text-tx-mute">{sub}</p>
227	      </div>
228	      {action && <div className="flex flex-none items-center gap-3">{action}</div>}
229	    </header>
230	  );
231	}
232	
233	/* ── Mailboxes ───────────────────────────────────────────────────────────
234	   The list the page exists for. Flat and open by default: previously every
235	   mailbox sat inside a collapsed per-domain accordion, so an account with one
236	   domain still had to expand something to see the one thing it owns. */
237	function MailboxesTab({ subscriptions }: { subscriptions: SubscriptionRow[] }) {
238	  const multi = subscriptions.length > 1;
239	
240	  return (
241	    <div className="flex flex-col gap-3">
242	      {subscriptions.map((sub) => {
243	        const atLimit = sub.mailboxes.length >= sub.planMailboxes;
244	        return (
245	          <Panel
246	            key={sub.id}
247	            // Only name the domain as a panel title when there is more than
248	            // one — on a single-domain account it is a heading that repeats
249	            // what every row underneath already says.
250	            title={multi ? sub.domainName : "Mailboxes"}
251	            sub={`${sub.planName} · ${sub.mailboxes.length}/${sub.planMailboxes} used · ${sub.planStorageGB} GB each`}
252	            bodyClass="gap-2"
253	          >
254	            {sub.mailboxes.length === 0 ? (
255	              <p className="py-2 text-[13px] text-tx-faint">
256	                No mailboxes on {sub.domainName} yet — create the first one below.
257	              </p>
258	            ) : (
259	              sub.mailboxes.map((m) => <MailboxItem key={m.id} mailbox={m} />)
260	            )}
261	            <AddMailboxForm subscriptionId={sub.id} domainName={sub.domainName} atLimit={atLimit} />
262	          </Panel>
263	        );
264	      })}
265	    </div>
266	  );
267	}
268	
269	/* ── Domains & DNS ───────────────────────────────────────────────────────
270	   Setup and diagnosis. Separated from the mailbox list because they are
271	   different jobs on different days: you configure DNS once, then come back
272	   only when mail starts landing in spam. */
273	function DomainsTab({ subscriptions }: { subscriptions: SubscriptionRow[] }) {
274	  return (
275	    <div className="flex flex-col gap-3">
276	      {subscriptions.map((sub) => {
277	        const reason = attentionReason(sub);
278	        return (
279	          <Panel
280	            key={sub.id}
281	            title={sub.domainName}
282	            sub={
283	              sub.expiresAt
284	                ? `${sub.planName} · renews ${new Date(sub.expiresAt).toLocaleDateString()}`
285	                : sub.planName
286	            }
287	            action={
288	              <span className="flex flex-wrap items-center gap-1.5">
289	                <span className={"chip-tone " + (sub.status === "ACTIVE" ? "chip-mint" : "chip-slate")}>
290	                  {sub.status}
291	                </span>
292	                {sub.external ? (
293	                  <span className={"chip-tone " + (sub.verified ? "chip-mint" : "chip-amber")}>
294	                    {sub.verified ? "Verified" : "Setup required"}
295	                  </span>
296	                ) : (
297	                  <span className="chip-tone chip-blue">Managed by Nxeon</span>
298	                )}
299	                {reason === "failed" && <span className="chip-tone chip-rose">Mailbox setup failed</span>}
300	              </span>
301	            }
302	            bodyClass="gap-3"
303	          >
304	            {sub.external ? (
305	              <EmailDnsSetup subscriptionId={sub.id} domainName={sub.domainName} verified={sub.verified} />
306	            ) : (
307	              <p className="rounded-[10px] border border-rim-soft bg-[rgba(72,148,255,0.05)] px-3 py-2 text-[12px] text-tx-mute">
308	                This domain is registered with Nxeon, so its mail DNS is managed for you — mailboxes go live
309	                automatically. Run the deliverability check below to confirm every record is actually published.
310	              </p>
311	            )}
312	            <DeliverabilityPanel subscriptionId={sub.id} domainName={sub.domainName} />
313	          </Panel>
314	        );
315	      })}
316	    </div>
317	  );
318	}
