21	import { db } from "@/lib/db";
22	import { checkRateLimit } from "@/lib/rate-limit";
23	import { resolveMailbox } from "@/lib/mail/imap";
24	import {
25	  mailcowConfigured,
26	  mcListAliases,
27	  mcAddAlias,
28	  mcDeleteAlias,
29	  mcListFilters,
30	  mcAddFilter,
31	  mcEditFilter,
32	  mcDeleteFilter,
33	  type MailcowAlias,
34	} from "@/lib/mailcow";
35	import { resetMailboxPassword } from "@/lib/actions-email-hosting";
36	import { safeHtml } from "@/lib/mail/render";
37	import { signatureHtmlToText, SIGNATURE_HTML_MAX } from "@/lib/mail/signature";
38	import {
39	  buildMailboxSieve,
40	  isNxeonSieve,
41	  MARK_AUTOREPLY,
42	  MARK_FORWARD,
43	  NXEON_SIEVE_DESC,
44	  NXEON_SIEVE_TYPE,
45	  type MailboxRuleState,
46	} from "@/lib/mail/sieve";
