48	export type Result = { ok: boolean; error?: string };
49	
50	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
51	
52	/** Serialisable mailbox settings the panel reads/writes. */
53	export type MailboxSettings = {
54	  address: string;
55	  domain: string;
56	  displayName: string;
57	  // Identity
58	  replyTo: string;
59	  organization: string;
60	  // Signature
61	  signature: string; // derived / legacy plain-text
62	  signatureHtml: string; // sanitized rich HTML (source of truth)
63	  signatureEnabled: boolean;
64	  signatureOnReply: boolean;
65	  signaturePlacement: "above" | "below";
66	  // Auto-reply
67	  autoReplyEnabled: boolean;
68	  autoReplySubject: string;
69	  autoReplyBody: string;
70	  autoReplyStart: string; // "YYYY-MM-DD" or ""
71	  autoReplyEnd: string; // "YYYY-MM-DD" or ""
72	  // Forwarding (stored)
73	  forwardingAddress: string;
74	  forwardKeepCopy: boolean;
75	  // Storage
76	  quotaMB: number | null;
77	};
78	
79	function domainOf(address: string): string {
80	  const at = address.lastIndexOf("@");
81	  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
82	}
83	
84	/** Format a stored Date as a `YYYY-MM-DD` string (or "" when null). */
85	function toDateInput(d: Date | null | undefined): string {
86	  if (!d) return "";
87	  try {
88	    return d.toISOString().slice(0, 10);
89	  } catch {
90	    return "";
91	  }
92	}
93	
94	/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
95	function fromDateInput(s: string | null | undefined): Date | null {
96	  const v = (s ?? "").trim();
97	  if (!v) return null;
98	  const d = new Date(`${v}T00:00:00.000Z`);
99	  return Number.isNaN(d.getTime()) ? null : d;
100	}
101	
102	/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
103	function gate(key: string, max: number, windowMs: number): Result | null {
104	  const r = checkRateLimit(key, { max, windowMs });
105	  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
106	  return null;
107	}
108	
109	/**
110	 * The domains the signed-in user has PROVEN they control.
111	 *
112	 * `verified: true` is load-bearing, not decoration. An alias is a mail-routing
113	 * change (`mcAddAlias` makes the shared Mailcow deliver an address somewhere),
114	 * so treating a bare subscription row as proof of domain control let a claimed —
115	 * not owned — domain silently intercept inbound mail. Same root cause as the
116	 * 2026-07-25 cross-tenant takeover: owning the ROW is not owning the DOMAIN.
117	 */
118	async function ownedDomains(userId: string): Promise<Set<string>> {
119	  const subs = await db.emailSubscription.findMany({
120	    where: { userId, status: { not: "CANCELLED" }, verified: true },
121	    select: { domainName: true },
122	  });
123	  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
124	}
