130	/** Load the current settings for a mailbox the caller owns. */
131	// ---------------------------------------------------------------------------
132	// Mailbox-row helpers — a resolved mailboxId is either a customer Mailbox.id or,
133	// for a staff-resolved COMPANY mailbox, "company:<CompanyMailbox.id>". Both
134	// tables now carry the same settings columns, so identity/signature/auto-reply/
135	// forwarding read and write the same way regardless of which backs the mailbox.
136	// This is the fix for the P2025 crash on Save changes: db.mailbox.update() threw
137	// for company mailboxes because no Mailbox row exists for them.
138	// ---------------------------------------------------------------------------
139	
140	function companyRowId(mailboxId: string): string | null {
141	  return mailboxId.startsWith("company:") ? mailboxId.slice("company:".length) : null;
142	}
143	
144	/** Read the settings-bearing row for a resolved mailbox from whichever table backs it. */
145	async function loadMailboxRow(mailboxId: string) {
146	  const cid = companyRowId(mailboxId);
147	  return cid
148	    ? db.companyMailbox.findUnique({ where: { id: cid } })
149	    : db.mailbox.findUnique({ where: { id: mailboxId } });
150	}
151	
152	/** Persist settings to whichever table backs the resolved mailbox (customer Mailbox or CompanyMailbox). */
153	async function updateMailboxRow(mailboxId: string, data: Prisma.MailboxUncheckedUpdateInput): Promise<void> {
154	  const cid = companyRowId(mailboxId);
155	  if (cid) {
156	    await db.companyMailbox.update({ where: { id: cid }, data: data as Prisma.CompanyMailboxUncheckedUpdateInput });
157	  } else {
158	    await db.mailbox.update({ where: { id: mailboxId }, data });
159	  }
160	}
