162	export async function getMailboxSettings(mailboxAddress?: string): Promise<MailboxSettings> {
163	  const { mailboxId, address } = await resolveMailbox(mailboxAddress);
164	  const row = await loadMailboxRow(mailboxId);
165	  const placement = row?.signaturePlacement === "above" ? "above" : "below";
166	  return {
167	    address,
168	    domain: domainOf(address),
169	    displayName: row?.displayName ?? "",
170	    replyTo: row?.replyTo ?? "",
171	    organization: row?.organization ?? "",
172	    signature: row?.signature ?? "",
173	    signatureHtml: row?.signatureHtml ?? "",
174	    signatureEnabled: row?.signatureEnabled ?? true,
175	    signatureOnReply: row?.signatureOnReply ?? true,
176	    signaturePlacement: placement,
177	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
178	    autoReplySubject: row?.autoReplySubject ?? "",
179	    autoReplyBody: row?.autoReplyBody ?? "",
180	    autoReplyStart: toDateInput(row?.autoReplyStart),
181	    autoReplyEnd: toDateInput(row?.autoReplyEnd),
182	    forwardingAddress: row?.forwardingAddress ?? "",
183	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
184	    quotaMB: row?.quotaMB ?? null,
185	  };
