533	export type AliasRow = { id: number; address: string; goto: string; active: boolean };
534	
535	function toAliasRows(list: MailcowAlias[]): AliasRow[] {
536	  return list.map((a) => ({ id: a.id, address: a.address, goto: a.goto, active: a.active }));
