539	/** List the aliases on the mailbox's domain. */
540	export async function listAliases(
541	  mailboxAddress?: string,
542	): Promise<{ ok: boolean; error?: string; aliases: AliasRow[] }> {
543	  const { user, address } = await resolveMailbox(mailboxAddress);
544	  const domain = domainOf(address);
545	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet.", aliases: [] };
546	
547	  const owned = await ownedDomains(user.id);
548	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain.", aliases: [] };
549	
550	  try {
551	    const list = await mcListAliases(domain);
552	    return { ok: true, aliases: toAliasRows(list) };
553	  } catch (e) {
554	    return { ok: false, error: friendly(e), aliases: [] };
555	  }
556	}
