558	/**
559	 * Add an alias on a domain the caller owns. `alias` may be a full address or a
560	 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
561	 * mailbox itself.
562	 */
563	export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
564	  const { user, address } = await resolveMailbox(mailboxAddress);
565	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
566	  if (limited) return limited;
567	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
568	
569	  let aliasAddr = (alias ?? "").trim().toLowerCase();
570	  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
571	  // Accept a bare local part — assume the mailbox's own domain.
572	  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
573	  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };
574	
575	  const owned = await ownedDomains(user.id);
576	  if (!owned.has(domainOf(aliasAddr))) {
577	    return { ok: false, error: "You can only add aliases on a domain you own." };
578	  }
579	
580	  const dest = (goto ?? "").trim() || address;
581	  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
582	  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };
583	
584	  try {
585	    await mcAddAlias(aliasAddr, dest);
586	    return { ok: true };
