916	/** Remove a mailbox the caller owns (via its subscription). */
917	export async function removeMailbox(mailboxId: string): Promise<Result> {
918	  const user = await requireUser();
919	
920	  const mailbox = await db.mailbox.findUnique({
921	    where: { id: mailboxId },
922	    include: { subscription: true },
923	  });
924	  if (!mailbox) return { error: "Mailbox not found." };
925	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
926	
927	  // Delete on Mailcow BEFORE dropping our row — and distinguish the two failure
928	  // modes, because they demand opposite actions:
929	  //
930	  //   - Mailcow REFUSED (reachable, returned an error): the mail server and our
931	  //     database disagree about this mailbox. Deleting our row here would leave a
932	  //     LIVE mailbox still receiving the customer's mail with no record of it in
933	  //     the product — silent data loss. Surface the error and keep the row.
934	  //   - Mailcow UNREACHABLE (transport failure): the server may just be down.
935	  //     Blocking removal forever on an outage is wrong, so we drop our row and
936	  //     tell the customer the mailbox itself may still exist and to retry once
937	  //     mail service is back.
938	  //
939	  // The previous `.catch(() => {})` collapsed both into "deleted, ok:true" — the
940	  // worse answer in every case.
941	  let mailcowUnreachable = false;
942	  if (mailcowConfigured()) {
943	    try {
944	      await mcDeleteMailbox(mailbox.address);
945	    } catch (e) {
946	      if (isMailcowUnreachable(e)) {
947	        mailcowUnreachable = true;
948	        console.warn(`[mailcow] delete ${mailbox.address}: unreachable, removing local record anyway:`, e);
949	      } else {
950	        console.error(`[mailcow] delete ${mailbox.address} REFUSED:`, e);
951	        return {
952	          error:
953	            "The mail server wouldn't remove this mailbox, so we've left it in place rather than lose your mail. Please try again in a moment, or contact support if it keeps happening.",
954	        };
955	      }
956	    }
957	  }
958	
959	  await db.mailbox.delete({ where: { id: mailbox.id } });
960	
961	  await db.auditLog.create({
962	    data: {
963	      userId: user.id,
964	      action: "mailbox.remove",
965	      detail: mailcowUnreachable ? `${mailbox.address} (mailcow unreachable — server-side delete not confirmed)` : mailbox.address,
966	    },
967	  });
968	  revalidatePath("/dashboard/email");
969	  return mailcowUnreachable
970	    ? {
971	        ok: true,
972	        warning:
973	          "Removed from your account. The mail server was unreachable, so the mailbox itself may still exist — it will be cleared when mail service is back, or contact support if messages keep arriving.",
974	      }
975	    : { ok: true };
976	}
