979	 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
980	 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
981	 */
982	export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
983	  const user = await requireUser();
984	
985	  const mailbox = await db.mailbox.findUnique({
