989	  if (!mailbox) return { error: "Mailbox not found." };
990	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
991	
992	  // A REFUSAL means the flip did not happen on the mail server, so writing our
993	  // status to SUSPENDED/ACTIVE would be a lie the customer acts on — a "suspended"
994	  // mailbox that keeps sending and receiving, or vice versa. Only an UNREACHABLE
995	  // server is tolerated (the state will reconcile), and even then the customer is
996	  // told the mail server did not confirm.
997	  let mailcowUnreachable = false;
998	  if (mailcowConfigured()) {
999	    try {
1000	      await mcSetMailboxActive(mailbox.address, !suspended);
1001	    } catch (e) {
1002	      if (isMailcowUnreachable(e)) {
1003	        mailcowUnreachable = true;
1004	        console.warn(`[mailcow] set active ${mailbox.address}: unreachable, updating local status anyway:`, e);
1005	      } else {
1006	        console.error(`[mailcow] set active ${mailbox.address} REFUSED:`, e);
1007	        return {
1008	          error: `The mail server wouldn't ${suspended ? "suspend" : "resume"} this mailbox, so nothing was changed. Please try again in a moment.`,
1009	        };
1010	      }
1011	    }
1012	  }
1013	
1014	  await db.mailbox.update({
1015	    where: { id: mailbox.id },
1016	    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
1017	  });
1018	
1019	  await db.auditLog.create({
1020	    data: {
1021	      userId: user.id,
1022	      action: suspended ? "mailbox.suspend" : "mailbox.resume",
1023	      detail: mailbox.address,
1024	    },
1025	  });
1026	  revalidatePath("/dashboard/email");
1027	  return mailcowUnreachable
1028	    ? {
1029	        ok: true,
1030	        warning: `Updated in your account, but the mail server was unreachable so it may not be ${suspended ? "suspended" : "active"} yet — it will reconcile when mail service is back.`,
